        "text": "Kiểm tra tuyến ống thử kín:\n- Toàn tuyến ống phải liền mạch, ống và phụ kiện không móp méo, hư hại vật lý, nứt vỡ\n- Các vị trí bơm nước vào phải là vị trí cao nhất, các vị trí xả kiệt nước phải là vị trí thấp nhất.",
