    "question": "Quy trình Nghiệm thu sinh trưởng quy định về tần suất thực hiện và tiêu chuẩn phân loại hiện trạng cây như thế nào?",
    "answers": [
      {
        "text": "Tần suất thực hiện: Tiến hành nghiệm thu sau khi trồng được 1 tháng. Định kỳ tần suất duy trì 1 tháng / 1 lần để kiểm tra, đánh giá và xếp loại.",
        "score": 3
      },
      {
        "text": "Phân loại Cây sống khỏe: Thân căng mọng nhiều nhựa, rễ đã ra rễ con, lá đã ra lá già và lá non.",
        "score": 2
      },
      {
        "text": "Phân loại Cây yếu: Cây có dấu hiệu bị sâu bệnh, bỏ cành, bỏ ngọn hoặc bị lệch tán.",
        "score": 3
      },
      {
        "text": "Phân loại Cây chết: Thân, lá khô héo, không còn rễ tươi (Yêu cầu chụp tối thiểu 2 ảnh: Ảnh biển tên và ảnh tổng thể để làm hồ sơ).",
        "score": 2
      }
    ]
