        "text": "Kiểm tra độ lệch tim cây và hố cây (sai số cho phép ± 20cm; cây trên tuyến phải thẳng hàng) và kiểm tra độ thẳng đứng (không nghiêng vẹo, lệch tâm quá 15%).",
